import argparse
import csv
from collections import OrderedDict


def count_non_empty(csv_path, null_tokens=<redacted>"", "na", "n/a", "null", "none", "-")):
    with open(csv_path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return OrderedDict()

        counts = OrderedDict((name, 0) for name in header)
        for row in reader:
            for i, value in enumerate(row):
                if i >= len(counts):
                    break
                if value is not None and value.strip().lower() not in null_tokens:<redacted>
    return counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    args = parser.parse_args()

    counts = count_non_empty(args.csv_file)
    if not counts:
        print("文件为空或没有表头")
        return

    width = max(len(name) for name in counts)
    for name, count in counts.items():
        print(f"{name:<{width}} : {count}")


if __name__ == "__main__":
    main()
